function log(message){state.history.push(message);renderHistory();}
function renderHistory(){const list=$('history');list.replaceChildren();for(const text of state.history){const li=document.createElement('li');li.textContent=text;list.append(li);}}
function setStage(stage){if(!stages[stage])throw Error('Unknown workflow stage');if(['inspect','choose'].includes(stage)&&!poolScreenReady()){stage='evaluate';notice('Complete the required whole-pool shotgun screen before inspecting or choosing a route.');}state.stage=stage;if(stage!=="prepare"&&mapPick)cancelMapPick();for(const b of document.querySelectorAll('[data-step]')){b.classList.toggle('active',b.dataset.step===stage);if(b.dataset.step===stage)b.setAttribute('aria-current','step');else b.removeAttribute('aria-current');}for(const p of document.querySelectorAll('[data-panel]'))p.hidden=p.dataset.panel!==stage;[$('stage-owner').textContent,$('stage-title').textContent]=stages[stage];renderMapPickControls();if(stage==='choose')renderChoice();if(stage==='inspect'){renderCells();renderReviewTarget();}const priorCue=nextActionTarget;updateNextAction();if(stage==='search'&&priorCue===nextActionTarget)returnToHereApproval();}
