  const controls=$('map-trip-controls');if(controls)controls.hidden=state.stage!=='prepare';
  if($('red-cutoff'))$('red-cutoff').disabled=state.busy;if($('confirm-red-cutoff'))$('confirm-red-cutoff').disabled=state.busy;
  for(const target of ['origin','destination']){$(target).disabled=state.busy;$(target+'-name').disabled=state.busy;$(target+'-address').disabled=state.busy;$('find-'+target+'-address').disabled=state.busy||addressLookupBusy[target];for(const id of ['pick-'+target,'map-pick-'+target]){const button=$(id);button.disabled=state.busy||!available;button.setAttribute('aria-pressed',String(mapPick===target));button.classList.toggle('active',mapPick===target);}}
