  $('map-instruction').textContent=mapPick?'Click to set '+(mapPick==='origin'?'start':'destination')+' · Escape to cancel':current()?'Click to select a cell for AVM and review · Double-click to open Street View':'Set the start and destination to begin. No prior trip is loaded.';
