    if(!matches.length){status.textContent='No usable address matches found. Try another address or set the point on the map.';return;}
    suppressNextActionScroll=true;
    if(!setTripPoint(target,[matches[0].latitude,matches[0].longitude],matches[0].label)){status.textContent='Wait for the active request to finish, then find the address again.';return;}
    showTripPointOnMap(target);
    const results=$(target+'-address-results'),options=[];
    const markSelected=index=>{for(const [optionIndex,option]of options.entries()){option.disabled=optionIndex===index;option.textContent=(optionIndex===index?'Current match: ':'Use instead: ')+matches[optionIndex].label;}};
    for(const [index,match]of matches.entries()){const option=document.createElement('button');option.type='button';option.addEventListener('click',()=>{if(state.busy||epoch!==addressLookupEpoch[target])return;resumeGuidedFocus();suppressNextActionScroll=true;if(setTripPoint(target,[match.latitude,match.longitude],match.label)){markSelected(index);showTripPointOnMap(target);status.textContent='Placed '+(target==='origin'?'S':'D')+' at '+match.label+'. Check the pin on the map. No route search was sent.';updateNextAction();suppressNextActionScroll=false;}});options.push(option);results.append(option);}
